def transform(grid):
    h, w = len(grid), len(grid[0])
    marked = set()
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            marked.update((r, c) for c in range(w))
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1:
            marked.update((r, c) for r in range(h))
    out = [row[:] for row in grid]
    for r, c in marked:
        out[r][c] = 2
    return out
